 const metresPerPixel=40075016.68557849*Math.cos(focus.center[1]*Math.PI/180)/(512*2**buildingMap.getZoom());
 const roofOffset=(currentFloor+1)*3/metresPerPixel*Math.sin(buildingMap.getPitch()*Math.PI/180);
