// Presentation only: retain official names and statistical joins unchanged.
function municipalityDisplayName(name,code){
 const aliases={'03014':'Alicante','03050':'El Campello','03065':'Elche','46250':'Valencia'};
 if(aliases[code])return aliases[code];
 return String(name??'').replace(/_+/g,' ').split('/').map(part=>{let text=part.replace(/\s+/g,' ').trim();const article=text.match(/^(.+),\s*(el|la|los|las|els|les|l['’])$/i);if(article){const prefix=article[2][0].toUpperCase()+article[2].slice(1);text=prefix+(/['’]$/.test(prefix)?'':' ')+article[1];}return text;}).join(' / ');
}
