async function loadTerritory(){try{const r=await fetch('assets/territory/municipalities.geojson?v=i7.1',{cache:'no-store'});if(!r.ok)throw Error(r.status);const data=await r.json();if(data.type!=='FeatureCollection'||!data.metadata)throw Error('Datos no válidos');territoryData={...data,features:data.features.map(f=>({...f,properties:{...f.properties,displayName:municipalityDisplayName(f.properties.name,f.properties.code)}}))};territoryMeta=data.metadata;territoryIndex=new Map(territoryData.features.map(f=>[f.properties.code,f.properties]));$('#choropleth-toggle').disabled=false;updateTerritoryMap();drawList();zoneView();}catch(e){$('#territory-legend').textContent='Datos oficiales no disponibles. No se muestra una capa inventada.';$('#choropleth-toggle').disabled=true;}}
